pragma solidity 0.8.10; pragma experimental ABIEncoderV2; interface IERC20 { event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address to, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom( address from, address to, uint256 amount ) external returns (bool); } library CustomErrors { error CANNOT_SET_TO_ADDRESS_ZERO(); error INITIATOR_NOT_AUTHORIZED(address actual, address expected); error CALLER_NOT_LENDING_POOL(address actual, address expected); error CANNOT_REPAY_FLASHLOAN(); error INVALID_AGGREGATOR(); error AGGREGATOR_CALL_FAILED(); error EXECUTION_NOT_AUTHORIZED(address owner, address caller, address target, bytes4 selector); error EXECUTION_REVERTED(); error NOT_OWNER(address owner, address caller); error OWNER_CHANGED(address originalOwner, address newOwner); error TARGET_INVALID(address target); error CALLER_NOT_VAULT_OWNER(address callerProxy, address vaultOwner); error CALLER_NOT_PROTOCOL_MANAGER(); error MANAGER_NOT_LISTED(); error VAULT_NOT_UNDER_MANAGEMENT(); error CALLER_NOT_SELECTED_MANAGER(); error PROXY_ALREADY_EXISTS(address owner); error MAX_OPERATIONS_REACHED(); error MINT_AMOUNT_GREATER_THAN_VAULT_DEBT(); error VAULT_VALUE_CHANGE_TOO_HIGH(); error FINAL_VAULT_RATIO_TOO_LOW(uint256 minRatio, uint256 actualRatio); error VAULT_NOT_AUTOMATED(); error VAULT_TRIGGER_RATIO_NOT_REACHED(uint256 actual, uint256 expected); error TARGETS_LENGTH_DIFFERENT_THAN_DATA_LENGTH(uint256 targetsLength, uint256 dataLength); error LOW_LEVEL_CALL_FAILED(); error REBALANCE_AMOUNT_CANNOT_BE_ZERO(); error VARIABLE_FEE_TOO_HIGH(uint256 maxVarFee, uint256 actualVarFee); } library WadRayMath { uint256 internal constant WAD = 1e18; uint256 internal constant HALF_WAD = 0.5e18; uint256 internal constant RAY = 1e27; uint256 internal constant HALF_RAY = 0.5e27; uint256 internal constant WAD_RAY_RATIO = 1e9; function wadMul(uint256 a, uint256 b) internal pure returns (uint256 c) { assembly { if iszero(or(iszero(b), iszero(gt(a, div(sub(not(0), HALF_WAD), b))))) { revert(0, 0) } c := div(add(mul(a, b), HALF_WAD), WAD) } } function wadDiv(uint256 a, uint256 b) internal pure returns (uint256 c) { assembly { if or(iszero(b), iszero(iszero(gt(a, div(sub(not(0), div(b, 2)), WAD))))) { revert(0, 0) } c := div(add(mul(a, WAD), div(b, 2)), b) } } function rayMul(uint256 a, uint256 b) internal pure returns (uint256 c) { assembly { if iszero(or(iszero(b), iszero(gt(a, div(sub(not(0), HALF_RAY), b))))) { revert(0, 0) } c := div(add(mul(a, b), HALF_RAY), RAY) } } function rayDiv(uint256 a, uint256 b) internal pure returns (uint256 c) { assembly { if or(iszero(b), iszero(iszero(gt(a, div(sub(not(0), div(b, 2)), RAY))))) { revert(0, 0) } c := div(add(mul(a, RAY), div(b, 2)), b) } } function rayToWad(uint256 a) internal pure returns (uint256 b) { assembly { b := div(a, WAD_RAY_RATIO) let remainder := mod(a, WAD_RAY_RATIO) if iszero(lt(remainder, div(WAD_RAY_RATIO, 2))) { b := add(b, 1) } } } function wadToRay(uint256 a) internal pure returns (uint256 b) { assembly { b := mul(a, WAD_RAY_RATIO) if iszero(eq(div(b, WAD_RAY_RATIO), a)) { revert(0, 0) } } } } interface IMIMOProxy { event Execute(address indexed target, bytes data, bytes response); event TransferOwnership(address indexed oldOwner, address indexed newOwner); function initialize() external; function getPermission( address envoy, address target, bytes4 selector ) external view returns (bool); function owner() external view returns (address); function minGasReserve() external view returns (uint256); function execute(address target, bytes calldata data) external payable returns (bytes memory response); function setPermission( address envoy, address target, bytes4 selector, bool permission ) external; function transferOwnership(address newOwner) external; function multicall(address[] calldata targets, bytes[] calldata data) external returns (bytes[] memory); } interface IMIMOProxyFactory { event DeployProxy(address indexed deployer, address indexed owner, address proxy); function isProxy(address proxy) external view returns (bool result); function VERSION() external view returns (uint256); function deploy() external returns (IMIMOProxy proxy); function deployFor(address owner) external returns (IMIMOProxy proxy); } interface IAccessController { event RoleAdminChanged(bytes32 indexed role, bytes32 indexed previousAdminRole, bytes32 indexed newAdminRole); event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender); event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender); function grantRole(bytes32 role, address account) external; function revokeRole(bytes32 role, address account) external; function renounceRole(bytes32 role, address account) external; function MANAGER_ROLE() external view returns (bytes32); function MINTER_ROLE() external view returns (bytes32); function hasRole(bytes32 role, address account) external view returns (bool); function getRoleMemberCount(bytes32 role) external view returns (uint256); function getRoleMember(bytes32 role, uint256 index) external view returns (address); function getRoleAdmin(bytes32 role) external view returns (bytes32); } interface IConfigProvider { struct CollateralConfig { address collateralType; uint256 debtLimit; uint256 liquidationRatio; uint256 minCollateralRatio; uint256 borrowRate; uint256 originationFee; uint256 liquidationBonus; uint256 liquidationFee; } event CollateralUpdated( address indexed collateralType, uint256 debtLimit, uint256 liquidationRatio, uint256 minCollateralRatio, uint256 borrowRate, uint256 originationFee, uint256 liquidatio